using MediatR; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using VetCommission.Application.Features.Procedures; using VetCommission.WebApi.Auth; using VetCommission.WebApi.Extensions;
namespace VetCommission.WebApi.Controllers;
[ApiController,Route("api/procedimentos"),Authorize(Policy=AuthorizationPolicyNames.ProceduresManage)] public sealed class ProceduresController(IMediator m):ControllerBase{[HttpGet]public async Task<IActionResult>List([FromQuery]int page=1,[FromQuery]int pageSize=20,[FromQuery]string? busca=null,[FromQuery]Guid? categoriaId=null,CancellationToken c=default)=>(await m.Send(new ListProceduresQuery(page,pageSize,busca,categoriaId),c)).ToActionResult(this);[HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken c)=>(await m.Send(new GetProcedureQuery(id),c)).ToActionResult(this);[HttpPost]public async Task<IActionResult>Create(SaveProcedureCommand x,CancellationToken c)=>(await m.Send(x,c)).ToActionResult(this);[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,SaveProcedureRequest x,CancellationToken c)=>(await m.Send(new SaveProcedureCommand(id,x.CategoryId,x.Code,x.Name,x.Description,x.DefaultValue),c)).ToActionResult(this);[HttpPost("{id:guid}/ativar")]public async Task<IActionResult>Activate(Guid id,CancellationToken c)=>(await m.Send(new SetProcedureActiveCommand(id,true),c)).ToActionResult(this);[HttpPost("{id:guid}/inativar")]public async Task<IActionResult>Deactivate(Guid id,CancellationToken c)=>(await m.Send(new SetProcedureActiveCommand(id,false),c)).ToActionResult(this);public sealed record SaveProcedureRequest(Guid CategoryId,string? Code,string Name,string? Description,decimal DefaultValue);}
